1	package org.jsoup.nodes;
2	
3	import org.jsoup.Connection;
4	import org.jsoup.Jsoup;
5	import org.jsoup.helper.HttpConnection;
6	import org.jsoup.helper.Validate;
7	import org.jsoup.parser.Tag;
8	import org.jsoup.select.Elements;
9	import org.jsoup.select.Evaluator;
10	import org.jsoup.select.Selector;
11	import org.jspecify.annotations.Nullable;
12	
13	import java.util.ArrayList;
14	import java.util.List;
15	
16	/**
17	 * An HTML Form Element provides ready access to the form fields/controls that are associated with it. It also allows a
18	 * form to easily be submitted.
19	 */
20	public class FormElement extends Element {
21	    // form controls linked while parsing, in parse (document) order. A link remembers the parent the parser finally
22	    // placed the control at, and stays valid only while the control keeps that exact parent and remains in the same
23	    // tree as this form. This drops the parser association automatically for controls that are later removed or
24	    // adopted elsewhere through some non-form parent (a nested descendant, or a fostered control moved out).
25	    private ArrayList<LinkedControl> linkedEls = new ArrayList<>();
26	    // all form-listed elements, per the HTML spec: button, fieldset, input, keygen, object, output, select, textarea
27	    private static final Evaluator formListed = Selector.evaluatorOf(
28	        "button, fieldset, input, keygen, object, output, select, textarea");
29	
30	    private static final class LinkedControl {
31	        final Element control;
32	        final Node anchorParent; // immediate parent the control had when the parser placed it
33	
34	        LinkedControl(Element control) {
35	            this.control = control;
36	            // constructed after the control has been inserted, so this is its final parse-time parent
37	            this.anchorParent = control.parentNode();
38	        }
39	
40	        boolean isValid(Node formRoot) {
41	            // a move or a detach changes the parent or the root; an untouched control still matches both
42	            return control.parentNode() == anchorParent && control.root() == formRoot;
43	        }
44	    }
45	
46	    /**
47	     * Create a new, standalone form element.
48	     *
49	     * @param tag        tag of this element
50	     * @param baseUri    the base URI
51	     * @param attributes initial attributes
52	     */
53	    public FormElement(Tag tag, @Nullable String baseUri, @Nullable Attributes attributes) {
54	        super(tag, baseUri, attributes);
55	    }
56	
57	    /**
58	     * Get the list of form control elements associated with this form. A control is associated either through a
59	     * matching {@code form="<id>"} attribute (resolved to the first form in the document with that id), or, when no
60	     * such attribute is present, through its nearest ancestor {@code <form>}; controls linked to this form by the
61	     * parser but relocated by parse rules (such as those fostered out of a form inside a table) are included too.
62	     * The list is freshly computed in document order and reflects the current state of the DOM.
63	     * @return form controls associated with this element.
64	     */
65	    public Elements elements() {
66	        Elements els = new Elements();
67	        Document owner = ownerDocument();
68	        if (owner == null) {
69	            // an orphaned, stand-alone form: fall back to its current descendants and still-valid linked controls
70	            final Node formRoot = root();
71	            els.addAll(select(formListed));
72	            for (LinkedControl linked : linkedEls) {
73	                if (linked.isValid(formRoot) && !els.contains(linked.control)) els.add(linked.control);
74	            }
75	            return els;
76	        }
77	
78	        // a form="<id>" reference resolves, in tree order, to the first <form> with that id
79	        String formId = id();
80	        boolean referencedFormsResolveHere = formId.length() == 0 || firstFormWithId(owner, formId) == this;
81	
82	        for (Element el : owner.select(formListed)) {
83	            if (isFormOwner(el, formId, referencedFormsResolveHere, owner))
84	                els.add(el);
85	        }
86	        return els; // owner.select yields elements in document order, and each is visited at most once
87	    }
88	
89	    private static @Nullable Element firstFormWithId(Document owner, String formId) {
90	        for (Element form : owner.select("form")) {
91	            if (formId.equals(form.id())) return form;
92	        }
93	        return null;
94	    }
95	
96	    /**
97	     * Determine whether this form is the form owner of the given control, following the HTML association rules:
98	     * an explicit {@code form} attribute wins and resolves to the first form with that id; otherwise the nearest
99	     * form ancestor owns it, falling back to the parser-established link for controls displaced by parse rules
100	     * (such as a control fostered out of a form inside a table). A parser link is only honoured while the control
101	     * keeps the parent and tree the parser left it in, so later removals or reparenting clear the association.
102	     */
103	    private boolean isFormOwner(Element el, String formId, boolean referencedFormsResolveHere, Node formRoot) {
104	        String referenced = el.attr("form");
105	        if (referenced.length() > 0)
106	            return referencedFormsResolveHere && referenced.equals(formId);
107	
108	        for (Element ancestor = el.parentElement(); ancestor != null; ancestor = ancestor.parentElement()) {
109	            if (ancestor.nameIs("form")) return ancestor == this;
110	        }
111	        // no form ancestor: retain the association established while parsing, unless the control has since moved
112	        for (LinkedControl linked : linkedEls) {
113	            if (linked.control == el) return linked.isValid(formRoot);
114	        }
115	        return false;
116	    }
117	
118	    /**
119	     * Add a form control element to this form.
120	     * @param element form control to add
121	     * @return this form element, for chaining
122	     */
123	    public FormElement addElement(Element element) {
124	        linkedEls.add(new LinkedControl(element));
125	        return this;
126	    }
127	
128	    @Override
129	    protected void removeChild(Node out) {
130	        super.removeChild(out);
131	        // a direct child being removed can no longer be a parser-linked control of this form
132	        linkedEls.removeIf(linked -> linked.control == out);
133	    }
134	
135	    /**
136	     * Prepare to submit this form. A Connection object is created with the request set up from the form values. This
137	     * Connection will inherit the settings and the cookies (etc) of the connection/session used to request this Document
138	     * (if any), as available in {@link Document#connection()}
139	     <p>You can then set up other options (like user-agent, timeout, cookies), then execute it.</p>
140	
141	     @return a connection prepared from the values of this form, in the same session as the one used to request it
142	     @throws IllegalArgumentException if the form's absolute action URL cannot be determined. Make sure you pass the
143	     document's base URI when parsing.
144	     */
145	    public Connection submit() {
146	        String action = hasAttr("action") ? absUrl("action") : baseUri();
147	        Validate.notEmpty(action, "Could not determine a form action URL for submit. Ensure you set a base URI when parsing.");
148	        Connection.Method method = attr("method").equalsIgnoreCase("POST") ?
149	                Connection.Method.POST : Connection.Method.GET;
150	
151	        Document owner = ownerDocument();
152	        Connection connection = owner != null? owner.connection().newRequest() : Jsoup.newSession();
153	        return connection.url(action)
154	                .data(formData())
155	                .method(method);
156	    }
157	
158	    /**
159	     * Get the data that this form submits. The returned list is a copy of the data, and changes to the contents of the
160	     * list will not be reflected in the DOM.
161	     * @return a list of key vals
162	     */
163	    public List<Connection.KeyVal> formData() {
164	        ArrayList<Connection.KeyVal> data = new ArrayList<>();
165	
166	        // iterate the form control elements and accumulate their values
167	        for (Element el: elements()) {
168	            if (!el.tag().isFormSubmittable()) continue; // contents are form listable, superset of submitable
169	            if (el.hasAttr("disabled")) continue; // skip disabled form inputs
170	            String name = el.attr("name");
171	            if (name.length() == 0) continue;
172	            String type = el.attr("type");
173	
174	            if (type.equalsIgnoreCase("button") || type.equalsIgnoreCase("image")) continue; // browsers don't submit these
175	
176	            if (el.nameIs("select")) {
177	                addSelectData(name, el, data);
178	            } else if ("checkbox".equalsIgnoreCase(type) || "radio".equalsIgnoreCase(type)) {
179	                // only add checkbox or radio if they have the checked attribute
180	                if (el.hasAttr("checked") && !isDisabledByFieldset(el, type)) {
181	                    final String val = el.val().length() >  0 ? el.val() : "on";
182	                    data.add(HttpConnection.KeyVal.create(name, val));
183	                }
184	            } else {
185	                if (isDisabledByFieldset(el, type)) continue;
186	                data.add(HttpConnection.KeyVal.create(name, el.val()));
187	            }
188	        }
189	        return data;
190	    }
191	
192	    private void addSelectData(String name, Element select, ArrayList<Connection.KeyVal> data) {
193	        if (isDisabledByFieldset(select, "")) return;
194	
195	        boolean multiple = select.hasAttr("multiple");
196	        Elements options = select.select("option");
197	        Element firstEnabled = null;
198	        boolean submitted = false;
199	
200	        for (Element option : options) {
201	            if (!optionEnabled(option)) continue;
202	            if (firstEnabled == null) firstEnabled = option;
203	            if (option.hasAttr("selected")) {
204	                data.add(HttpConnection.KeyVal.create(name, option.val()));
205	                submitted = true;
206	                if (!multiple) return; // single-select submits the first selected enabled option, in final order
207	            }
208	        }
209	
210	        if (!submitted && !multiple && firstEnabled != null) {
211	            // single-select with no enabled selected option falls back to the first enabled option
212	            data.add(HttpConnection.KeyVal.create(name, firstEnabled.val()));
213	        }
214	        // multi-select with no enabled selections, or a single-select with no enabled options, submits nothing
215	    }
216	
217	    private boolean optionEnabled(Element option) {
218	        if (option.hasAttr("disabled")) return false;
219	        // an option is also unavailable when its nearest enclosing <optgroup> is disabled
220	        for (Element ancestor = option.parentElement();
221	             ancestor != null && ancestor.nameIs("optgroup");
222	             ancestor = ancestor.parentElement()) {
223	            if (ancestor.hasAttr("disabled")) return false;
224	        }
225	        return true;
226	    }
227	
228	    /**
229	     * Per the HTML spec, a disabled fieldset excludes all of its descendant controls except those within the subtree
230	     * of its first direct {@code <legend>} child. The exception does not extend to siblings or nested fieldsets outside
231	     * that legend. An {@code <input type="hidden">} is not disabled by a fieldset.
232	     */
233	    private boolean isDisabledByFieldset(Element control, String type) {
234	        if ("hidden".equalsIgnoreCase(type)) return false;
235	        Element ancestor = control.parent();
236	        while (ancestor != null) {
237	            if (ancestor.nameIs("fieldset") && ancestor.hasAttr("disabled")) {
238	                Element legend = firstLegendChild(ancestor);
239	                if (legend == null || !isDescendant(control, legend)) return true;
240	                // control is inside the exempt first legend; continue checking ancestors outside of this fieldset
241	                ancestor = ancestor.parent();
242	            } else {
243	                ancestor = ancestor.parent();
244	            }
245	        }
246	        return false;
247	    }
248	
249	    private @Nullable Element firstLegendChild(Element fieldset) {
250	        for (Element child : fieldset.children()) {
251	            if (child.nameIs("legend")) return child;
252	        }
253	        return null;
254	    }
255	
256	    private boolean isDescendant(Element node, Element ancestor) {
257	        Node parent = node.parentNode();
258	        while (parent != null) {
259	            if (parent == ancestor) return true;
260	            parent = parent.parentNode();
261	        }
262	        return false;
263	    }
264	
265	    @Override
266	    public FormElement clone() {
267	        return (FormElement) super.clone();
268	    }
269	
270	    @Override
271	    protected FormElement doClone(@Nullable Node parent) {
272	        FormElement clone = (FormElement) super.doClone(parent);
273	        // don't share the parser-linked list; its anchors reference the source tree's nodes, and the clone's
274	        // descendants stay associated through their form ancestry
275	        clone.linkedEls = new ArrayList<>();
276	        return clone;
277	    }
278	}
