package org.jsoup.nodes;

import org.jsoup.Connection;
import org.jsoup.Jsoup;
import org.junit.jupiter.api.Test;

import java.util.List;

import static org.junit.jupiter.api.Assertions.*;

class FormElementProbeTest {
    private static String dataString(FormElement form) {
        StringBuilder sb = new StringBuilder();
        for (Connection.KeyVal kv : form.formData()) {
            if (sb.length() > 0) sb.append('&');
            sb.append(kv.key()).append('=').append(kv.value());
        }
        return sb.toString();
    }

    @Test void toggleDisabledAfterRead() {
        Document doc = Jsoup.parse("<form id=f><input name=a value=A>" +
            "<fieldset id=fs><legend><input name=leg value=L></legend><input name=b value=B></fieldset></form>");
        FormElement form = doc.expectForm("#f");
        assertEquals("a=A&leg=L", dataString(form));

        doc.selectFirst("[name=a]").attr("disabled", "");
        assertEquals("leg=L", dataString(form));
        doc.selectFirst("[name=a]").removeAttr("disabled");
        assertEquals("a=A&leg=L", dataString(form));

        doc.selectFirst("#fs").removeAttr("disabled");
        assertEquals("a=A&leg=L&b=B", dataString(form));
        doc.selectFirst("#fs").attr("disabled", "");
        assertEquals("a=A&leg=L", dataString(form));
    }

    @Test void multipleCheckedRadiosSameName() {
        // parser-level duplicate checked: each checked radio is emitted (jsoup rule)
        Document doc = Jsoup.parse("<form><input type=radio name=r value=1 checked>" +
            "<input type=radio name=r value=2 checked></form>");
        assertEquals("r=1&r=2", dataString(doc.expectForm("form")));
    }

    @Test void selectDisabledSelect() {
        Document doc = Jsoup.parse("<form><select name=s disabled><option value=a selected></select></form>");
        assertEquals("", dataString(doc.expectForm("form")));
    }

    @Test void innerLegendDoesNotReallowOuterBlock() {
        String html = "<form id=f><fieldset disabled>" +
            "<fieldset disabled><legend><input name=x value=X></legend></fieldset>" +
            "</fieldset></form>";
        assertEquals("", dataString(Jsoup.parse(html).expectForm("#f")));
    }

    @Test void nestedEnabledFieldsetUnderDisabledOuter() {
        // task rule: everything under a disabled fieldset is excluded but first legend subtree
        String html = "<form id=f><fieldset disabled>" +
            "<fieldset><input name=x value=X></fieldset>" +
            "</fieldset></form>";
        assertEquals("", dataString(Jsoup.parse(html).expectForm("#f")));
    }

    @Test void externalControlReparentToOtherFormDropsAttr() {
        Document doc = Jsoup.parse("<form id=f></form><form id=g></form><input form=f name=a value=A>");
        FormElement f = doc.expectForm("#f");
        FormElement g = doc.expectForm("#g");
        assertEquals("a=A", dataString(f));
        Element a = doc.selectFirst("[name=a]");
        a.removeAttr("form");
        g.appendChild(a);
        assertEquals("", dataString(f));
        assertEquals("a=A", dataString(g));
    }

    @Test void implicitTagCompletion() {
        String html = "<form id=f><select name=s><option value=a selected><option value=b>" +
            "<input name=t value=T</form>";
        assertEquals("s=a&t=T", dataString(Jsoup.parse(html).expectForm("#f")));
    }

    @Test void optionInsideDisabledOptgroupFallback() {
        // all options disabled (incl. via optgroup) -> no entry at all
        String html = "<form><select name=s>" +
            "<optgroup disabled><option value=a></optgroup>" +
            "<option value=b disabled></select></form>";
        assertEquals("", dataString(doc0(html).expectForm("form")));
    }

    private Document doc0(String html) { return Jsoup.parse(html); }

    @Test void snapshotIndependenceDeep() {
        FormElement form = Jsoup.parse("<form id=f><input name=a value=A><input name=b value=B></form>").expectForm("#f");
        List<Connection.KeyVal> d1 = form.formData();
        List<Connection.KeyVal> d2 = form.formData();
        assertNotSame(d1, d2);
        d1.clear();
        assertEquals(2, d2.size());
        assertEquals(2, form.formData().size());
    }

    @Test void orderAfterEdits() {
        Document doc = Jsoup.parse("<form id=f><input name=a value=A><input name=b value=B></form>" +
            "<input form=f name=c value=C>");
        FormElement form = doc.expectForm("#f");
        assertEquals("a=A&b=B&c=C", dataString(form));
        // toggle c's form attr back and forth
        doc.selectFirst("[name=c]").attr("form", "other"); // invalid id -> drops out
        assertEquals("a=A&b=B", dataString(form));
        doc.selectFirst("[name=c]").attr("form", "f");
        assertEquals("a=A&b=B&c=C", dataString(form));
    }

    @Test void selectOptionSelectedToggledAfterRead() {
        Document doc = Jsoup.parse("<form id=f><select name=s><option id=o1 value=a><option id=o2 value=b selected></select></form>");
        FormElement form = doc.expectForm("#f");
        assertEquals("s=b", dataString(form));
        doc.selectFirst("#o2").removeAttr("selected");
        // no selected -> first enabled option fallback
        assertEquals("s=a", dataString(form));
        doc.selectFirst("#o1").attr("disabled", "");
        assertEquals("s=b", dataString(form)); // first enabled is now b
    }

    @Test void repeatedReadsDoNotMutate() {
        String html = "<form id=f><input type=checkbox name=c checked><select name=s><option value=a selected>" +
            "<option value=b selected></select></form>";
        Document doc = Jsoup.parse(html);
        FormElement form = doc.expectForm("#f");
        String before = doc.html();
        for (int i = 0; i < 3; i++) assertEquals("c=on&s=a", dataString(form));
        assertEquals(before, doc.html());
    }
}

