package org.jsoup.nodes;

import org.jsoup.Jsoup;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

class FormElementStructureProbeTest {
    @Test void fosteredFormStructure() {
        String html = "<table><form id=f><tr><td><input name=user value=u></td>" +
            "<td><input name=pass value=p></td></tr></form></table>";
        Document doc = Jsoup.parse(html);
        FormElement form = doc.expectForm("#f");
        Element user = doc.selectFirst("[name=user]");
        System.out.println("FORM PARENT OF USER: " + user.parent());
        System.out.println("elements count: " + form.elements().size());
        for (Element el : form.elements()) {
            System.out.println(" - " + el.tagName() + " " + el.attr("name") + " parent=" + el.parent().tagName());
        }
    }

    @Test void optionInDisabledSelectFieldsetCombo() {
        String html = "<form id=f><fieldset disabled><select name=s><option value=a selected>" +
            "</select></fieldset></form>";
        FormElement form = Jsoup.parse(html).expectForm("#f");
        // select itself is inside disabled fieldset -> fieldset check on select excludes it
        assertEquals("", probeData(form));
    }

    private static String probeData(FormElement form) {
        StringBuilder sb = new StringBuilder();
        form.formData().forEach(kv -> sb.append(kv.key()).append('=').append(kv.value()).append('&'));
        return sb.toString();
    }
}

